"""
Recommendation output models.

Defines the typed schemas for the output of the recommendation engine,
matching the structured JSON expected from the Groq LLM.

Maps to: Architecture §3.5 — Output Display Layer schema.
"""

from __future__ import annotations

from typing import Any

from pydantic import BaseModel, Field

from models.restaurant import BudgetTier


class Recommendation(BaseModel):
    """A single ranked recommendation generated by the LLM."""

    restaurant_id: int | str = Field(
        ...,
        description="Unique identifier of the restaurant.",
    )
    restaurant_name: str = Field(
        ...,
        description="Name of the restaurant.",
    )
    cuisines: list[str] = Field(
        ...,
        description="List of cuisines served.",
    )
    rating: float = Field(
        ...,
        description="Restaurant aggregate rating.",
    )
    estimated_cost_for_two: int = Field(
        ...,
        description="Estimated cost for two people in INR.",
    )
    budget_tier: BudgetTier = Field(
        ...,
        description="Budget tier (low, medium, high).",
    )
    location: str = Field(
        ...,
        description="Restaurant location/neighbourhood.",
    )
    rank: int = Field(
        ...,
        ge=1,
        description="Rank assigned by the LLM (1 is the top recommendation).",
    )
    explanation: str = Field(
        ...,
        description="AI-generated explanation detailing why this restaurant fits the user's preferences.",
    )
    address: str | None = Field(
        default=None,
        description="Full street address (optional).",
    )


class RecommendationList(BaseModel):
    """The complete response from the recommendation engine."""

    summary: str = Field(
        ...,
        description="AI-generated high-level summary of the recommended set.",
    )
    recommendations: list[Recommendation] = Field(
        ...,
        description="List of ranked recommendations.",
    )
    metadata: dict[str, Any] = Field(
        default_factory=dict,
        description="Operational metadata (e.g. candidates_considered, filters_applied, llm_model).",
    )
